import React from 'react';
import {AbsoluteFill, Audio, Sequence, staticFile} from 'remotion';
import {Captions} from './Captions';
import {shots} from './data';
import {Slot} from './Slot';
import {audio, slots} from './slots';
import {theme} from './theme';

// Generated by shotlist from test-clip.mp4.
// 9 shots, 450 frames at 30 fps. The timings below match the source
// frame for frame: change what is inside a slot (src/slots.tsx), not when it starts.
export const Main: React.FC = () => {
  return (
    <AbsoluteFill style={{backgroundColor: theme.bg}}>
      {/* s01 · hook · 0.00s to 1.50s */}
      <Sequence name="s01 hook" from={0} durationInFrames={45}>
        <Slot shot={shots[0]} fill={slots.s01} />
      </Sequence>
      {/* s02 · setup · 1.50s to 3.00s · cut on the beat */}
      <Sequence name="s02 setup" from={45} durationInFrames={45}>
        <Slot shot={shots[1]} fill={slots.s02} />
      </Sequence>
      {/* s03 · setup · 3.00s to 3.80s · cut on the beat */}
      <Sequence name="s03 setup" from={90} durationInFrames={24}>
        <Slot shot={shots[2]} fill={slots.s03} />
      </Sequence>
      {/* s04 · setup · 3.80s to 5.00s · cut off the beat */}
      <Sequence name="s04 setup" from={114} durationInFrames={36}>
        <Slot shot={shots[3]} fill={slots.s04} />
      </Sequence>
      {/* s05 · proof · 5.00s to 6.30s · cut on the beat */}
      <Sequence name="s05 proof" from={150} durationInFrames={39}>
        <Slot shot={shots[4]} fill={slots.s05} />
      </Sequence>
      {/* s06 · proof · 6.30s to 8.00s · cut off the beat */}
      <Sequence name="s06 proof" from={189} durationInFrames={51}>
        <Slot shot={shots[5]} fill={slots.s06} />
      </Sequence>
      {/* s07 · proof · 8.00s to 10.00s · cut on the beat */}
      <Sequence name="s07 proof" from={240} durationInFrames={60}>
        <Slot shot={shots[6]} fill={slots.s07} />
      </Sequence>
      {/* s08 · payoff · 10.00s to 12.00s · cut on the beat */}
      <Sequence name="s08 payoff" from={300} durationInFrames={60}>
        <Slot shot={shots[7]} fill={slots.s08} />
      </Sequence>
      {/* s09 · cta · 12.00s to 15.00s · cut on the beat */}
      <Sequence name="s09 cta" from={360} durationInFrames={90}>
        <Slot shot={shots[8]} fill={slots.s09} />
      </Sequence>
      <Captions />
      {audio ? <Audio src={/^https?:/.test(audio) ? audio : staticFile(audio)} /> : null}
    </AbsoluteFill>
  );
};
